"""Writes res://data/fragments.gd from fragment_gen.py (spec 2.2).

DEVELOPMENT-TIME ONLY. Run it when seeds or base rates are retuned, then commit
the generated file. Names and seeds are frozen constants at runtime: a player
must see the same name and the same sigil for the same Fragment, forever.

    python3 tools/gen_fragments.py
"""

from __future__ import annotations

import pathlib
import sys

import fragment_gen as fg

HEADER = '''class_name Fragments
extends RefCounted

## The 50 Fragment definitions (spec 2.2). GENERATED by tools/gen_fragments.py.
##
## Do not hand-edit and do not generate anything here at runtime: players must
## see the same name and the same sigil for the same Fragment, forever. To
## change the set, edit tools/fragment_gen.py, re-run tools/gen_fragments.py,
## then re-run tools/balance_sim.py before shipping.
##
## seed drives the procedural sigil (shaders/sigil.gdshader); it is kept below
## 2^24 so it survives the trip through a 32-bit shader float exactly.
## base_rate is Flux/sec BEFORE the tier multiplier in Balance.TIER_MULTIPLIER.

const ALL: Array[Dictionary] = [
'''

FOOTER = ''']

const COUNT := 50

static func get_by_id(id: String) -> Dictionary:
	for f in ALL:
		if f["id"] == id:
			return f
	return {}


static func index_of(id: String) -> int:
	for i in ALL.size():
		if ALL[i]["id"] == id:
			return i
	return -1


static func ids() -> Array[String]:
	var out: Array[String] = []
	for f in ALL:
		out.append(f["id"])
	return out


static func of_tier(tier: int) -> Array[Dictionary]:
	var out: Array[Dictionary] = []
	for f in ALL:
		if f["tier"] == tier:
			out.append(f)
	return out


static func of_set(set_id: String) -> Array[Dictionary]:
	var out: Array[Dictionary] = []
	for f in ALL:
		if f["set_id"] == set_id:
			out.append(f)
	return out


static func set_ids() -> Array[String]:
	var out: Array[String] = []
	for f in ALL:
		if not out.has(f["set_id"]):
			out.append(f["set_id"])
	out.sort()
	return out
'''


def main() -> int:
    frags = fg.build_fragments()
    errors = fg.validate(frags)
    if errors:
        for e in errors:
            print(f"ERROR: {e}", file=sys.stderr)
        return 1

    lines = [HEADER]
    for f in frags:
        lines.append(
            '\t{"id": "%s", "name": "%s", "tier": %d, "seed": %d, '
            '"base_rate": %.2f, "set_id": "%s"},\n'
            % (f.id, f.name, f.tier, f.seed, f.base_rate, f.set_id)
        )
    lines.append(FOOTER)

    out = pathlib.Path(__file__).resolve().parent.parent / "data" / "fragments.gd"
    out.write_text("".join(lines), encoding="utf-8")

    sizes: dict[str, int] = {}
    for f in frags:
        sizes[f.set_id] = sizes.get(f.set_id, 0) + 1
    print(f"wrote {out} ({len(frags)} fragments)")
    print("set sizes: " + ", ".join(f"{k}={v}" for k, v in sorted(sizes.items())))
    print("tier counts: " + ", ".join(
        f"T{t}={sum(1 for f in frags if f.tier == t)}" for t in sorted(fg.TIER_COUNTS)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
